#if defined(CONFIG_EMUL) || defined(__DOXYGEN__)
#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/emul_bbram.h>

static inline const struct emul *z_bbram_emul_from_dev(const struct device *dev)
{
	STRUCT_SECTION_FOREACH(emul, emul) {
		if (emul->dev == dev) {
			return emul;
		}
	}

	return NULL;
}

static inline int bbram_emul_set_invalid(const struct device *dev, bool is_invalid)
{
	const struct emul *emul = z_bbram_emul_from_dev(dev);
	const struct emul_bbram_driver_api *api;

	if (emul == NULL || emul->backend_api == NULL) {
		return -ENODEV;
	}

	api = (const struct emul_bbram_driver_api *)emul->backend_api;
	if (api->set_invalid == NULL) {
		return -ENOTSUP;
	}

	return api->set_invalid(emul, is_invalid);
}

